input.oldString:
const draw = () => {
    ctx.clearRect(0, 0, W, H);
    // ship
    ctx.save();
    ctx.translate(ship.x, ship.y);
    ctx.fillStyle = ship.shield > 0 ? 'rgba(0,255,255,0.5)' : 'white';
    ctx.beginPath();
    ctx.moveTo(0, -ship.r);
    ctx.lineTo(ship.r, ship.r);
    ctx.lineTo(-ship.r, ship.r);
    ctx.closePath();
    ctx.fill();
    ctx.restore();
    // asteroids
    ctx.fillStyle = 'gray';
    for (const a of asteroids) {
      ctx.beginPath();
      ctx.arc(a.x, a.y, a.r, 0, Math.PI * 2);
      ctx.fill();
    }
    // fuels
    ctx.fillStyle = 'orange';
    for (const f of fuels) {
      ctx.beginPath();
      ctx.arc(f.x, f.y, f.r, 0, Math.PI * 2);
      ctx.fill();
    }
    // UI
    ctx.fillStyle = 'white';
    ctx.font = '16px sans-serif';
    ctx.fillText('Score: ' + score, 10, 20);
    if (ship.shield > 0) {
      ctx.fillText('Shield', 10, 40);
    }
    if (gameOver) {
      ctx.fillStyle = 'red';
      ctx.font = '48px sans-serif';
      ctx.textAlign = 'center';
      ctx.fillText('Game Over', W / 2, H / 2);
    }
  };

input.newString:
const draw = () => {
    // background gradient
    const bg = ctx.createLinearGradient(0, 0, 0, H);
    bg.addColorStop(0, '#000014');
    bg.addColorStop(1, '#000030');
    ctx.fillStyle = bg;
    ctx.fillRect(0, 0, W, H);
    // stars
    ctx.fillStyle = 'white';
    for (const s of stars) {
      ctx.fillRect(s.x, s.y, s.size, s.size);
      // slight twinkle
      s.x -= 0.5;
      if (s.x < 0) { s.x = W; s.y = rand(0, H); }
    }
    // ship
    ctx.save();
    ctx.translate(ship.x, ship.y);
    ctx.fillStyle = ship.shield > 0 ? 'rgba(0,255,255,0.5)' : '#00ffcc';
    ctx.strokeStyle = '#fff';
    ctx.lineWidth = 2;
    ctx.beginPath();
    ctx.moveTo(0, -ship.r);
    ctx.lineTo(ship.r, ship.r);
    ctx.lineTo(-ship.r, ship.r);
    ctx.closePath();
    ctx.fill();
    ctx.stroke();
    ctx.restore();
    // asteroids with shading
    for (const a of asteroids) {
      const grad = ctx.createRadialGradient(a.x, a.y, a.r * 0.2, a.x, a.y, a.r);
      grad.addColorStop(0, '#777');
      grad.addColorStop(1, '#222');
      ctx.fillStyle = grad;
      ctx.beginPath();
      ctx.arc(a.x, a.y, a.r, 0, Math.PI * 2);
      ctx.fill();
    }
    // fuels
    ctx.fillStyle = 'orange';
    for (const f of fuels) {
      ctx.beginPath();
      ctx.arc(f.x, f.y, f.r, 0, Math.PI * 2);
      ctx.fill();
    }
    // UI
    ctx.fillStyle = 'white';
    ctx.font = '16px sans-serif';
    ctx.textAlign = 'left';
    ctx.fillText('Score: ' + score, 10, 20);
    if (ship.shield > 0) {
      ctx.fillText('Shield', 10, 40);
    }
    if (gameOver) {
      ctx.fillStyle = 'red';
      ctx.font = '48px sans-serif';
      ctx.textAlign = 'center';
      ctx.fillText('Game Over', W / 2, H / 2);
    }
  };

